def distinctSubsequences(S):
    n = len(S)
    dp = [[0 for _ in range(26)] for _ in range(n+1)]
    for j in range(26):
        dp[0][j] = 1
    for i in range(1, n+1):
        for j in range(26):
            dp[i][j] = dp[i-1][j]
            if ord(S[i-1]) - ord('a') == j:
                dp[i][j] += dp[i-1][j]
    return sum(dp[n]) % (10**9 + 7)
```
