def distinctSubsequences(S):
    seen = set()
    dp = [1] + [0] * len(S)
    for i in range(len(S)):
        if S[i] not in seen:
            for j in range(i):
                dp[i] += dp[j]
            seen.add(S[i])
    return dp[-1] % (10**9 + 7)
